use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn longest_consecutive(root:Option<Rc<RefCell<TreeNode>>>)->i32{fn f(n:&Option<Rc<RefCell<TreeNode>>>,p:i32,len:i32,b:&mut i32){if let Some(x)=n{let q=x.borrow();let l=if q.val==p+1{len+1}else{1};*b=(*b).max(l);f(&q.left,q.val,l,b);f(&q.right,q.val,l,b);}}if root.is_none(){return 0}let v=root.as_ref().unwrap().borrow().val;let mut b=0;f(&root,v-1,0,&mut b);b}}
